import sys

def max_Product(arr):
    if len(arr) < 2:
        return None
    max1 = max2 = -sys.maxsize - 1
    min1 = min2 = sys.maxsize
    for num in arr:
        # Update max values
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num
        # Update min values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num
    return (max1, max2) if max1 * max2 > min1 * min2 else (min1, min2)
